insert into public.cles_examen (module_id, question, reponse, explication) values
('n4m4', 28, 'Protéger d’abord l’enfant, écarter le moniteur des enfants et informer les autorités compétentes', 'Le berger protège les brebis des loups (Jean 10.11-12) ; couvrir un abus, c’est se rendre complice. La justice doit pouvoir faire son travail (Romains 13.3-4).'),
('n4m4', 29, 'Ils prièrent leur Dieu et établirent une garde jour et nuit', '« Nous priâmes notre Dieu, et nous établîmes une garde jour et nuit pour nous défendre contre leurs attaques » (Néhémie 4.9).'),
('n4m5', 0, 'En étant transformé par le renouvellement de l’intelligence', 'Romains 12.2 : soyez transformés par le renouvellement de l’intelligence, afin que vous discerniez quelle est la volonté de Dieu.'),
('n4m5', 1, 'Éprouver, tester puis approuver ce qui est authentique', 'Dokimazô évoque le test d’un métal précieux : on éprouve, puis on approuve ce qui a résisté à l’épreuve.'),
('n4m5', 2, 'Il est exercé par l’usage, comme par un entraînement', 'Hébreux 5.14 : ceux dont le jugement est exercé par l’usage ; le verbe gumnazô évoque l’entraînement de l’athlète.'),
('n4m5', 3, 'Tout n’est pas utile, et tout n’édifie pas', '1 Corinthiens 10.23 : Tout est permis, mais tout n’est pas utile ; tout est permis, mais tout n’édifie pas.'),
('n4m5', 4, 'Faire tout pour la gloire de Dieu', '1 Corinthiens 10.31 : soit que vous mangiez, soit que vous buviez, soit que vous fassiez quelque autre chose, faites tout pour la gloire de Dieu.'),
('n4m5', 5, 'De se souiller par les mets et le vin du roi', 'Daniel 1.8 : Daniel résolut de ne pas se souiller par les mets du roi et par le vin dont le roi buvait.'),
('n4m5', 6, 'Un essai de dix jours avec des légumes et de l’eau', 'Daniel 1.12 : Éprouve tes serviteurs pendant dix jours, et qu’on nous donne des légumes à manger et de l’eau à boire.'),
('n4m5', 7, 'Chacun doit être pleinement persuadé dans son esprit, sans juger les autres', 'Romains 14.5 : que chacun ait en son esprit une pleine conviction ; et Romains 14.1 demande de ne pas discuter des opinions.'),
('n4m5', 8, 'Parce que Dieu a fait l’homme à son image', 'Genèse 9.6 : Si quelqu’un verse le sang de l’homme, par l’homme son sang sera versé ; car Dieu a fait l’homme à son image.'),
('n4m5', 9, 'Que Dieu forme la personne dans le sein de sa mère et la voit déjà', 'Psaume 139.13,16 : tu m’as tissé dans le sein de ma mère ; quand je n’étais qu’une masse informe, tes yeux me voyaient.'),
('n4m5', 10, 'Parce qu’elles craignaient Dieu', 'Exode 1.17 : les sages-femmes craignirent Dieu, et ne firent point ce que leur avait dit le roi d’Égypte ; elles laissèrent vivre les enfants.'),
('n4m5', 11, 'Au récit de la création dans la Genèse', 'Matthieu 19.4-5 : N’avez-vous pas lu que le créateur, au commencement, fit l’homme et la femme… ? Jésus cite Genèse 1.27 et 2.24.'),
('n4m5', 12, 'Je ne te condamne pas non plus : va, et ne pèche plus', 'Jean 8.11 : Je ne te condamne pas non plus : va, et ne pèche plus. Jésus unit la grâce et la vérité.'),
('n4m5', 13, 'Faux', 'Toute personne est créée à l’image de Dieu (Genèse 1.27) ; Jésus, plein de grâce et de vérité, accueille sans mépris tout en appelant à la sainteté.'),
('n4m5', 14, 'L’entourer, l’écouter et l’aider concrètement à accueillir son enfant', 'Une Église qui défend la vie (Psaume 139) doit aussi accompagner concrètement les mères en détresse, avec la compassion de Jésus.'),
('n4m5', 15, 'Ce qui est vrai, honorable, juste, pur et aimable', 'Philippiens 4.8 : que tout ce qui est vrai, honorable, juste, pur, aimable… soit l’objet de vos pensées.'),
('n4m5', 16, 'Saisir les occasions favorables de faire le bien', 'Exagorazô signifie racheter, saisir ; kairos désigne le moment favorable. Il faut saisir chaque occasion de faire le bien.'),
('n4m5', 17, 'L’amour de l’argent', '1 Timothée 6.10 : l’amour de l’argent est une racine de tous les maux ; ce n’est pas l’argent lui-même.'),
('n4m5', 18, 'Il a refusé, pour montrer que la grâce de Dieu ne s’achète pas', '2 Rois 5.16 : L’Éternel, dont je suis le serviteur, est vivant ! je n’accepterai pas.'),
('n4m5', 19, 'La lèpre de Naaman s’attacha à lui', '2 Rois 5.27 : la lèpre de Naaman s’attacha à Guéhazi, qui sortit de devant Élisée blanc de lèpre comme la neige.'),
('n4m5', 20, 'Parce que c’était l’héritage de ses pères, et il ne voulait pas le donner', '« Que l’Éternel me garde de te donner l’héritage de mes pères ! » (1 Rois 21.3 ; voir Lévitique 25.23).'),
('n4m5', 21, 'Parce que le pays appartient à l’Éternel', '« Les terres ne se vendront point à perpétuité ; car le pays est à moi, car vous êtes chez moi comme étrangers et comme habitants » (Lévitique 25.23).'),
('n4m5', 22, 'D’avoir maudit Dieu et le roi', '« Naboth a maudit Dieu et le roi ! » (1 Rois 21.13).'),
('n4m5', 23, '« N’es-tu pas un assassin et un voleur ? »', '« Ainsi parle l’Éternel : N’es-tu pas un assassin et un voleur ? » (1 Rois 21.19).'),
('n4m5', 24, 'Parce qu’Achab s’humilia devant lui', '« As-tu vu comment Achab s’est humilié devant moi ? Parce qu’il s’est humilié devant moi, je ne ferai pas venir le malheur pendant sa vie » (1 Rois 21.29).'),
('n4m5', 25, 'Suivre la multitude pour faire le mal', '« Tu ne suivras point la multitude pour faire le mal ; et tu ne déposeras point dans un procès en te mettant du côté du grand nombre, pour violer la justice » (Exode 23.2).'),
('n4m5', 26, 'Ils aveuglent ceux qui ont les yeux ouverts et corrompent les paroles des justes', '« Tu ne recevras point de présent ; car les présents aveuglent ceux qui ont les yeux ouverts et corrompent les paroles des justes » (Exode 23.8).'),
('n4m5', 27, 'Pour le muet et la cause de tous les délaissés', '« Ouvre ta bouche pour le muet, pour la cause de tous les délaissés » (Proverbes 31.8).'),
('n4m5', 28, 'Refuser l’échange, prier pour tous les candidats et laisser les membres voter selon leur conscience', 'Le présent qui achète une décision corrompt (Exode 23.8) ; la chaire n’est pas une tribune partisane, et l’Église prie pour toutes les autorités (1 Timothée 2.1-2).'),
('n4m5', 29, 'Par l’usage, en étant exercé', '« La nourriture solide est pour les hommes faits, pour ceux dont le jugement est exercé par l’usage à discerner ce qui est bien et ce qui est mal » (Hébreux 5.14).'),
('n4m6', 0, 'Une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas', 'Hébreux 11.1 : Or la foi est une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas.'),
('n4m6', 1, 'C’est par la foi', 'Le mot pistei, c’est par la foi, rythme tout le chapitre : par la foi Abel, Noé, Abraham, Moïse, Rahab…'),
('n4m6', 2, 'Que Dieu existe et qu’il est le rémunérateur de ceux qui le cherchent', 'Hébreux 11.6 : il faut que celui qui s’approche de Dieu croie que Dieu existe, et qu’il est le rémunérateur de ceux qui le cherchent.'),
('n4m6', 3, 'Faux', 'Abraham a menti, Moïse a tué un Égyptien, Rahab était une prostituée, Gédéon doutait : ils ont été retenus pour leur foi, non pour leur perfection.'),
('n4m6', 4, 'Sur Jésus, le chef et le consommateur de la foi', 'Hébreux 12.2 : ayant les regards sur Jésus, le chef et le consommateur de la foi.'),
('n4m6', 5, 'Il battait du blé dans le pressoir pour le cacher', 'Juges 6.11-12 : Gédéon battait du froment au pressoir pour le mettre à l’abri de Madian ; l’ange lui dit : L’Éternel est avec toi, vaillant héros !'),
('n4m6', 6, 'Pour qu’Israël ne se glorifie pas en disant que sa propre main l’avait délivré', 'Juges 7.2 : Le peuple que tu as avec toi est trop nombreux… il pourrait en tirer gloire contre moi, et dire : C’est ma main qui m’a délivré.'),
('n4m6', 7, 'Que toutes les familles de la terre soient bénies en lui', 'Genèse 12.3 : et toutes les familles de la terre seront bénies en toi.'),
('n4m6', 8, 'Il savait que Dieu est compatissant et pourrait faire grâce à Ninive', 'Jonas 4.2 : je savais que tu es un Dieu compatissant et miséricordieux, lent à la colère et riche en bonté, et qui te repens du mal.'),
('n4m6', 9, 'Ils ont cru à Dieu, jeûné et se sont détournés de leur mauvaise voie', 'Jonas 3.5-10 : les gens de Ninive crurent à Dieu, publièrent un jeûne, se revêtirent de sacs, et Dieu vit qu’ils revenaient de leur mauvaise voie.'),
('n4m6', 10, 'Par une question de Dieu sur sa compassion pour Ninive', 'Jonas 4.11 : Et moi, je n’aurais pas pitié de Ninive, la grande ville… ? Le livre se termine sur cette question.'),
('n4m6', 11, 'Barnabas et Saul', 'Actes 13.2 : Mettez-moi à part Barnabas et Saul pour l’œuvre à laquelle je les ai appelés.'),
('n4m6', 12, 'Elle servait le Seigneur et jeûnait', 'Actes 13.2 : Pendant qu’ils servaient le Seigneur dans leur ministère et qu’ils jeûnaient, le Saint-Esprit dit…'),
('n4m6', 13, 'De toute nation, de toute tribu, de tout peuple et de toute langue', 'Apocalypse 7.9 : une grande foule, que personne ne pouvait compter, de toute nation, de toute tribu, de tout peuple, et de toute langue.'),
('n4m6', 14, 'Parce que les gens ne peuvent croire en celui dont ils n’ont pas entendu parler', 'Romains 10.14 : Comment croiront-ils en celui dont ils n’ont pas entendu parler ? Et comment en entendront-ils parler, s’il n’y a personne qui prêche ?'),
('n4m6', 15, 'J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi', '2 Timothée 4.7 : J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi.'),
('n4m6', 16, 'Pour annoncer la puissance de Dieu à la génération future', 'Psaume 71.18 : afin que j’annonce ta force à la génération présente, ta puissance à la génération future.'),
('n4m6', 17, 'La montagne d’Hébron, où habitaient les fils d’Anak', 'Josué 14.12 : Donne-moi donc cette montagne dont l’Éternel a parlé dans ce temps-là ; car tu as appris alors qu’il s’y trouve des Anakim.'),
('n4m6', 18, 'Parce qu’il avait pleinement suivi la voie de l’Éternel', 'Josué 14.14 : C’est ainsi que Caleb… a eu jusqu’à ce jour Hébron pour héritage, parce qu’il avait pleinement suivi la voie de l’Éternel, le Dieu d’Israël.'),
('n4m6', 19, '2 Timothée 2.2 : confie-le à des hommes fidèles, capables de l’enseigner aussi à d’autres', '2 Timothée 2.2 décrit une chaîne de transmission : Paul, Timothée, des hommes fidèles, et d’autres encore.'),
('n4m6', 20, 'Il faisait partie des sept choisis pour le service des tables', 'Il fut choisi parmi les sept pour la distribution aux veuves, comme « homme plein de foi et d’Esprit-Saint » (Actes 6.5).'),
('n4m6', 21, 'Parce qu’ils ne pouvaient résister à sa sagesse et à l’Esprit par lequel il parlait', 'Incapables de le réfuter, ils fabriquèrent une accusation de blasphème (Actes 6.10-13).'),
('n4m6', 22, 'La gloire de Dieu et Jésus debout à la droite de Dieu', '« vit la gloire de Dieu et Jésus debout à la droite de Dieu » (Actes 7.55-56).'),
('n4m6', 23, '« Seigneur, ne leur impute pas ce péché ! »', 'À genoux, il s’écria d’une voix forte : « Seigneur, ne leur impute pas ce péché ! » (Actes 7.60), comme Jésus en Luc 23.34.'),
('n4m6', 24, 'Témoin', 'Martys désigne celui qui atteste ce qu’il a vu ; Paul appelle Étienne « ton témoin » (Actes 22.20).'),
('n4m6', 25, 'Les dispersés allaient de lieu en lieu annonçant la Parole', '« Ceux qui avaient été dispersés allaient de lieu en lieu, annonçant la bonne nouvelle de la parole » (Actes 8.4).'),
('n4m6', 26, 'Faux', 'Pierre distingue celui qui souffre comme malfaiteur de celui qui souffre « comme chrétien » (1 Pierre 4.15-16).'),
('n4m6', 27, 'Par le sang de l’agneau, la parole de leur témoignage et le refus de craindre la mort', '« Ils l’ont vaincu à cause du sang de l’agneau et à cause de la parole de leur témoignage, et ils n’ont pas aimé leur vie jusqu’à craindre la mort » (Apocalypse 12.11).'),
('n4m6', 28, 'Sois fidèle jusqu’à la mort, et je te donnerai la couronne de vie', '« Sois fidèle jusqu’à la mort, et je te donnerai la couronne de vie » (Apocalypse 2.10).'),
('n4m6', 29, 'Pleurer avec eux, réclamer justice par les voies légitimes, refuser la vengeance et prier pour les agresseurs', 'Étienne a nommé le péché mais prié pour ses bourreaux ; « ne vous vengez point vous-mêmes » (Romains 12.19 ; Matthieu 5.44).')
